// Generated by `build.rs` from the `impl Policy` blocks under `src/policies`.
// Do not edit: change the policy, or `tmpl/registry.tmpl`, and this follows.

/// Every policy this build carries, in name order.
///
/// The order is the names', so a report, a completion list and a refusal all name the policies the
/// same way round. The table is written out by `build.rs` in the same pass that reads the names, so
/// a row and the policy it names cannot disagree.
pub static POLICIES: &[crate::PolicyEntry] = &[
    crate::PolicyEntry {
        name: crate::policies::psd_basic::PsdBasic::NAME,
        extensions: crate::policies::psd_basic::PsdBasic::EXTENSIONS,
        chunker: &crate::policies::psd_basic::PsdBasic,
    },
];

/// The policy called `name`, if this build carries one.
#[must_use]
pub fn policy(name: &str) -> Option<&'static crate::PolicyEntry> {
    POLICIES.iter().find(|policy| policy.name == name)
}

/// The policy claiming `extension`, if one does.
///
/// One container is claimed by one policy at most — the build refuses two — so what cuts a file is
/// never a matter of which policy was looked at first.
#[must_use]
pub fn claiming(extension: &str) -> Option<&'static crate::PolicyEntry> {
    POLICIES
        .iter()
        .find(|policy| policy.extensions.contains(&extension))
}

/// The name of every policy this build carries, in the order the table holds them.
pub fn names() -> impl Iterator<Item = &'static str> {
    POLICIES.iter().map(|policy| policy.name)
}
